import{_ as s,o,c as a,a4 as i}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"华为手机 Termux 开机自启动 sshd 记录","description":"","frontmatter":{"title":"华为手机 Termux 开机自启动 sshd 记录","date":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/华为手机Termux开机自启动sshd记录.md","filePath":"posts/华为手机Termux开机自启动sshd记录.md"}'),t={name:"posts/华为手机Termux开机自启动sshd记录.md"};function d(r,e,l,h,n,c){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="华为手机-termux-开机自启动-sshd-记录" tabindex="-1">华为手机 Termux 开机自启动 sshd 记录 <a class="header-anchor" href="#华为手机-termux-开机自启动-sshd-记录" aria-label="Permalink to &quot;华为手机 Termux 开机自启动 sshd 记录&quot;">​</a></h1><blockquote><p>2026-08-01 · 设备：POT-AL00a（EMUI 13 / Android 10 / 无 Root） 目标：手机重启后 <code>sshd</code> 自动监听 8022，<code>ssh huawei-phone</code> 即连即用</p></blockquote><hr><h2 id="结论-可直接照做" tabindex="-1">结论（可直接照做） <a class="header-anchor" href="#结论-可直接照做" aria-label="Permalink to &quot;结论（可直接照做）&quot;">​</a></h2><h3 id="_1-安装" tabindex="-1">1. 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to &quot;1. 安装&quot;">​</a></h3><ul><li>Termux（F-Droid/GitHub 版）+ Termux:Boot 0.8.1，两个 APK 必须<strong>同一签名</strong>（termux-boot 才能执行脚本）</li></ul><h3 id="_2-华为设置-必须对-termux-和-termux-boot-两个应用都做" tabindex="-1">2. 华为设置（必须对 Termux 和 Termux:Boot 两个应用都做） <a class="header-anchor" href="#_2-华为设置-必须对-termux-和-termux-boot-两个应用都做" aria-label="Permalink to &quot;2. 华为设置（必须对 Termux 和 Termux:Boot 两个应用都做）&quot;">​</a></h3><ul><li><strong>电池优化</strong>：设置 → 应用和服务 → 权限管理 → 右上角「特殊访问权限」→ 电池优化 → 显示「所有应用」→ 分别设为「不允许」</li><li><strong>应用启动管理</strong>：设置 → 应用和服务 → 应用启动管理 → 分别点开 → 关闭「自动管理」→ 手动管理三个开关全开（允许自启动 / 允许关联启动 / 允许后台活动）</li><li><strong>网络</strong>：设置 → 电池 → 更多电池设置 → 休眠时始终保持网络连接 → 开启</li><li><strong>最近任务</strong>：Termux 和 Termux:Boot 各自下拉加锁</li></ul><h3 id="_3-开机脚本-termux-boot-start-sshd-sh" tabindex="-1">3. 开机脚本 <code>~/.termux/boot/start-sshd.sh</code> <a class="header-anchor" href="#_3-开机脚本-termux-boot-start-sshd-sh" aria-label="Permalink to &quot;3. 开机脚本 \`~/.termux/boot/start-sshd.sh\`&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">#!/data/data/com.termux/files/usr/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">echo</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">=== boot </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">$(</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">date</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ===</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">/data/data/com.termux/files/usr/bin/sshd</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -D</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 8022</span></span>
<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">}</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &gt;&gt;</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> /data/data/com.termux/files/home/boot.log </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">2&gt;&amp;1</span></span></code></pre></div><p>要点：</p><ul><li>必须 <strong>绝对路径</strong>（Android 10+ 开机时无 Termux 环境变量，相对路径会找不到命令）</li><li><code>sshd -D</code> <strong>前台模式</strong>：防止 TermuxService 无通知被杀导致 sshd 存活不了（Termux issue #4657）</li><li><code>chmod 755</code></li><li>脚本在 <code>~/.termux/boot/</code> 下，目录不存在需 <code>mkdir -p ~/.termux/boot</code></li></ul><hr><h2 id="排查过程与根因" tabindex="-1">排查过程与根因 <a class="header-anchor" href="#排查过程与根因" aria-label="Permalink to &quot;排查过程与根因&quot;">​</a></h2><h3 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to &quot;症状&quot;">​</a></h3><ul><li>开机后 <code>com.termux.boot</code> 进程能启动、JobScheduler 也有调度记录，但脚本<strong>不执行</strong>（boot.log 无新增、8022 不监听）</li></ul><h3 id="根因-两层" tabindex="-1">根因（两层） <a class="header-anchor" href="#根因-两层" aria-label="Permalink to &quot;根因（两层）&quot;">​</a></h3><ol><li><strong>华为开机把 <code>com.termux</code> 主应用标记为 <code>stopped=true</code></strong><ul><li>判断：<code>dumpsys package com.termux | grep stopped=</code></li><li>termux-boot 0.8.1 <strong>自己不执行脚本</strong>，它只是 BootReceiver → BootJobService → <code>startForegroundService</code> 转发 intent 给 <code>com.termux</code> 的 TermuxService 来跑脚本（见 BootJobService.java 源码）</li><li>Android 中 stopped 应用收不到任何隐式 intent → 转发被丢弃 → 脚本永不执行</li></ul></li><li><strong>手机管家设置没真正覆盖/保存</strong> → 手动管理三开关全开 + 电池优化不允许后解决</li></ol><h3 id="关键验证手段" tabindex="-1">关键验证手段 <a class="header-anchor" href="#关键验证手段" aria-label="Permalink to &quot;关键验证手段&quot;">​</a></h3><ul><li><code>dumpsys package &lt;pkg&gt; | grep stopped=</code>：看是否 stopped</li><li><code>dumpsys jobscheduler | grep termux</code>：看 BootJobService job 是否调度、卡在哪个约束（曾见 <code>WITHIN_QUOTA</code> 未满足）</li><li><code>run-as com.termux cat ~/boot.log</code>：确认脚本是否执行（注意 adb shell 嵌套引号会被吞，用 base64 或 <code>/data/local/tmp</code> 中转写文件）</li><li><code>am start -n com.termux/.app.TermuxActivity</code>：解除 stopped、拉起主进程（曾用它让 job 立即执行成功，反向证实根因）</li></ul><h3 id="排除的坑-供参考" tabindex="-1">排除的坑（供参考） <a class="header-anchor" href="#排除的坑-供参考" aria-label="Permalink to &quot;排除的坑（供参考）&quot;">​</a></h3><ul><li>无 Root 设备 <code>/data/data/com.termux/files/**</code> 只能 <code>run-as com.termux</code> 或 ssh 写入，adb shell 直写 Permission denied</li><li><code>cmd package set-stopped-state</code> 在 Android 10 不存在</li><li>RIO-UL00（EMUI 4.1）曾因 hwPfwService 强制停止第三方应用彻底无解，此方案适用于 EMUI 10+（POT-AL00a）</li></ul><hr><h1 id="rio-ul00-emui-4-1-android-6-0-1-arm64-开机自启动-sshd" tabindex="-1">RIO-UL00（EMUI 4.1 / Android 6.0.1 / arm64）开机自启动 sshd <a class="header-anchor" href="#rio-ul00-emui-4-1-android-6-0-1-arm64-开机自启动-sshd" aria-label="Permalink to &quot;RIO-UL00（EMUI 4.1 / Android 6.0.1 / arm64）开机自启动 sshd&quot;">​</a></h1><blockquote><p>2026-08-01 · 设备：RIO-UL00（EMUI 4.1 / Android 6 / 无 Root） 目标：手机重启后 <code>sshd</code> 自动监听 8022，<code>ssh huawei-phone-1</code> 即连即用 状态：✅ 已验证成功</p></blockquote><h2 id="与-pot-al00a-的关键差异" tabindex="-1">与 POT-AL00a 的关键差异 <a class="header-anchor" href="#与-pot-al00a-的关键差异" aria-label="Permalink to &quot;与 POT-AL00a 的关键差异&quot;">​</a></h2><ul><li><strong>POT（EMUI 13）</strong>：手机管家「应用启动管理」手动管理三开关全开 + 电池优化「不允许」即可</li><li><strong>RIO（EMUI 4.1）</strong>：<strong>必须用手机管家「受保护应用」列表</strong>（受保护=常驻内存/白名单），仅设启动管理不够。pfw（<code>hwPfwService</code>）开机 <code>StopPackagesThread</code> 会硬性 force-stop 第三方应用，只有把 Termux 加入受保护列表才会跳过</li><li>验证 pfw 生效：<code>logcat -d | grep HsmCacheData</code> 看到 <code>com.termux_1, com.termux.boot_1</code>（<code>_1</code> = 已加入白名单/受保护）；之前未配置时是 <code>forceStopPkg com.termux</code></li></ul><h2 id="rio-特有注意事项" tabindex="-1">RIO 特有注意事项 <a class="header-anchor" href="#rio-特有注意事项" aria-label="Permalink to &quot;RIO 特有注意事项&quot;">​</a></h2><ul><li><strong>Termux 版本</strong>：0.119.0-beta.3（versionCode 1022，minSdk 21，targetSdk 28）+ termux-boot 0.8.1，用 <code>pm install --user 0 -t</code> 绕过华为安装拦截</li><li><strong>UID</strong>：重装后 UID 10095 = <code>u0_a95</code>（<code>~/.ssh/config</code> 的 User 要对应）</li><li><strong>ssh 别名</strong>：<code>huawei-phone-1</code>（192.168.31.200:8022，User u0_a95，密钥免密已配）</li><li><strong>Termux 启动自检</strong>：<code>pidof com.termux</code> / <code>ps | grep u0_a95</code>，Android 6 的 <code>ps -A | grep</code> 可能匹配不到，用 <code>ps | grep</code> 或 <code>pidof</code></li><li><strong><code>ss -tln</code> 在 adb shell 下不显示 8022</strong>（权限受限），验证监听用 <code>pidof sshd</code> + 实际 SSH 连接更可靠</li><li>boot.log 因 adb 权限读不到，走 <code>ssh huawei-phone-1 cat ~/boot.log</code></li></ul><h2 id="开机脚本-termux-boot-start-sshd-sh-与-pot-相同" tabindex="-1">开机脚本 <code>~/.termux/boot/start-sshd.sh</code>（与 POT 相同） <a class="header-anchor" href="#开机脚本-termux-boot-start-sshd-sh-与-pot-相同" aria-label="Permalink to &quot;开机脚本 \`~/.termux/boot/start-sshd.sh\`（与 POT 相同）&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">#!/data/data/com.termux/files/usr/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">echo</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">=== boot </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">$(</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">date</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">)</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ===</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &gt;&gt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/data/com.termux/files/home/boot.log</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">/data/data/com.termux/files/usr/bin/sshd</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -D</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 8022</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &gt;&gt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/data/com.termux/files/home/boot.log</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> 2&gt;&amp;1</span></span></code></pre></div><p><code>chmod 755</code>，目录 <code>~/.termux/boot/</code> 不存在需先 <code>mkdir -p</code></p><h2 id="验证结果-rio" tabindex="-1">验证结果（RIO） <a class="header-anchor" href="#验证结果-rio" aria-label="Permalink to &quot;验证结果（RIO）&quot;">​</a></h2><ul><li>重启后 <code>com.termux</code>（PID ~3654）+ <code>com.termux.boot</code>（PID ~3611）均在运行</li><li>进程链：<code>/usr/bin/sh → sshd → sshd → bash</code>（boot 脚本执行 + 已接受连接）</li><li><code>timeout 8 ssh -o StrictHostKeyChecking=no huawei-phone-1 echo SSH_AUTOSTART_OK</code> → <code>SSH_AUTOSTART_OK</code></li><li>boot.log：<code>=== boot Sat Aug 1 20:55:31 CST 2026 ===</code></li></ul><hr><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><ul><li>重启后：<code>com.termux</code> + <code>com.termux.boot</code> 均启动，<code>sshd</code> 进程自动运行，8022 监听</li><li><code>timeout 10 ssh -o StrictHostKeyChecking=no huawei-phone echo OK</code> → 直接连上</li></ul><hr><h2 id="相关文件" tabindex="-1">相关文件 <a class="header-anchor" href="#相关文件" aria-label="Permalink to &quot;相关文件&quot;">​</a></h2><ul><li>电脑侧 SSH 配置：<code>~/.ssh/config</code> → <code>huawei-phone</code>（192.168.31.253:8022，User u0_a34）</li><li>手机侧：<code>/data/data/com.termux/files/home/.termux/boot/start-sshd.sh</code>、<code>~/boot.log</code></li></ul>`,40)])])}const k=s(t,[["render",d]]);export{u as __pageData,k as default};
